function A = lu − gauss (A)
% LU factorization without pivoting
[n,n] = size(A); for i=1:n-1; pivot = A(i,i);
for k=i+1:n; A(k,i)=A(k,i)/pivot;
for j=i+1:n; A (k, j) = A (k, j) − A (k, i) ∗ A (i, j);
end;end; end
